import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../services/backend/backend_api.dart';
import '../../../services/backend/weather_cache_service.dart';
import '../../../core/services/device_location_service.dart';
import '../../../models/weather/weather_model.dart';
import '../../weather/widgets/manual_location_picker.dart';
import '../../../widgets/app_navigation_scaffold.dart';

class WeatherScreen extends ConsumerStatefulWidget{const WeatherScreen({super.key});@override ConsumerState<WeatherScreen> createState()=>_WeatherScreenState();}
class _WeatherScreenState extends ConsumerState<WeatherScreen>{
 WeatherData? _weather;String? _error;bool _loading=true;
 @override void initState(){super.initState();_load();}
 Future<void> _load({bool refresh=false})async{setState((){_loading=true;if(refresh)_error=null;});try{final loc=await ref.read(deviceLocationServiceProvider).resolveCurrentLocation();
      WeatherData w;
      if(loc!=null){ w=await ref.read(backendApiProvider).getWeatherByCoordinates(latitude:loc.latitude,longitude:loc.longitude,label:loc.label); }
      else { final saved=await ref.read(deviceLocationServiceProvider).loadLastWeatherPlace(); w=saved!=null?await ref.read(backendApiProvider).getWeatherByPlace(district:saved['district']!,taluk:saved['taluk']!,village:saved['village']!):await ref.read(backendApiProvider).getWeatherByPlace(district:'Shivamogga'); }await ref.read(weatherCacheServiceProvider).save(_toMap(w));if(mounted)setState((){_weather=w;_loading=false;_error=null;});}catch(e){final cached=await ref.read(weatherCacheServiceProvider).load();if(cached!=null){try{final w=WeatherData.fromMap(cached);if(mounted)setState((){_weather=w;_loading=false;_error=e.toString().replaceFirst('Exception: ','');});return;}catch(_){}}if(mounted)setState((){_loading=false;_error=e.toString().replaceFirst('Exception: ','');});}}
 Map<String,dynamic> _toMap(WeatherData w)=>{'source':w.source,'location':{'name':w.locationName,'resolved_level':w.resolvedLevel,'timezone':w.timezone,'latitude':w.latitude,'longitude':w.longitude},'place':{'district':w.district,'locality':w.locality},'current':{'temperature':w.temperature,'humidity':w.humidity,'wind_kmh':w.windKmh,'precipitation_mm':w.precipitationMm,'rain_mm':w.rainMm,'weather_code':w.weatherCode},'next_24h':{'precipitation_mm':w.next24hPrecipitationMm,'precipitation_probability_max':w.next24hPrecipitationProbability,'et0_mm':w.next24hEt0Mm},'hourly':w.hourly.map((h)=>{'time':h.time,'temperature':h.temperature,'precipitation_probability':h.precipitationProbability,'precipitation_mm':h.precipitationMm,'weather_code':h.weatherCode}).toList(),'daily':w.forecast.map((d)=>{'date':d.date,'temperature_max':d.temperatureMax,'temperature_min':d.temperatureMin,'precipitation_mm':d.precipitationMm,'precipitation_probability':d.precipitationProbability,'et0_mm':d.et0Mm,'weather_code':d.weatherCode}).toList(),'guidance':{'spraying':w.guidance.spraying,'drying':w.guidance.drying,'transport':w.guidance.transport,'irrigation':w.guidance.irrigation,'status_line':w.guidance.statusLine},'updated_at':w.updatedAt.toIso8601String(),'fetched_at':w.fetchedAt.toIso8601String()};
 @override Widget build(BuildContext c){final s=Theme.of(c).colorScheme;final w=_weather;return AppNavigationScaffold(title:'Weather',selectedIndex:1,actions:[IconButton(onPressed:()=>_load(refresh:true),icon:const Icon(Icons.refresh_rounded))],body:RefreshIndicator(onRefresh:()=>_load(refresh:true),child:ListView(padding:const EdgeInsets.fromLTRB(18,12,18,32),children:[if(_error!=null)Column(crossAxisAlignment:CrossAxisAlignment.start,children:[_errorBanner(s,_error!),TextButton.icon(onPressed:()=>showManualLocationPicker(context,ref,onSelected:(d,t,v)async{final w=await ref.read(backendApiProvider).getWeatherByPlace(district:d,taluk:t,village:v);if(mounted)setState((){_weather=w;_error=null;});}),icon:const Icon(Icons.location_on_outlined),label:const Text('Choose Karnataka location'))]),_hero(c,w),if(_loading&&w==null)const Center(child:Padding(padding:EdgeInsets.all(30),child:CircularProgressIndicator())),if(w!=null)...[_section(c,"Today's farm guidance"),_guidance(c,w),_section(c,'Hourly forecast'),_hourly(c,w),_section(c,'7-day forecast'),_daily(c,w),_rainChips(c,w)]]]));}
 Widget _errorBanner(ColorScheme s,String e)=>Container(margin:const EdgeInsets.only(bottom:12),padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:s.secondaryContainer,borderRadius:BorderRadius.circular(14)),child:Text(e,style:TextStyle(color:s.error,fontWeight:FontWeight.w600)));
 Widget _hero(BuildContext c,WeatherData? w){final s=Theme.of(c).colorScheme;return Container(padding:const EdgeInsets.fromLTRB(18,18,18,14),decoration:BoxDecoration(color:s.primary,borderRadius:BorderRadius.circular(26)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(w?.locationName??'Current location',style:TextStyle(color:s.onPrimary,fontSize:17,fontWeight:FontWeight.w800)),Text(w?.district??'Local weather',style:TextStyle(color:s.onPrimary.withValues(alpha:.72),fontSize:11))])),IconButton(onPressed:()=>_load(refresh:true),icon:Icon(Icons.refresh_rounded,color:s.onPrimary))]),Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(w==null?'--°C':'${w.temperature?.round()??'--'}°C',style:TextStyle(color:s.onPrimary,fontSize:43,fontWeight:FontWeight.w800)),Text(w?.weatherDescription??'Loading weather',style:TextStyle(color:s.onPrimary,fontSize:15))])),Icon(_glyph(w?.weatherCode),color:s.onPrimary,size:56)]),const SizedBox(height:5),Text(w?.guidance.statusLine??'Getting local weather',style:TextStyle(color:s.onPrimary.withValues(alpha:.85),fontSize:12)),const SizedBox(height:14),Row(children:[_metric(s,'Rain chance','${w?.next24hPrecipitationProbability.round()??'--'}%'),_metric(s,'Humidity','${w?.humidity?.round()??'--'}%'),_metric(s,'Wind','${w?.windKmh?.round()??'--'} km/h'),_metric(s,'Max/Min',w?.forecast.isNotEmpty==true?'${w!.forecast.first.temperatureMax?.round()??'--'}° / ${w.forecast.first.temperatureMin?.round()??'--'}°':'-- / --')]),const SizedBox(height:10),Text(w==null?'':'Updated ${TimeOfDay.fromDateTime(w.updatedAt).format(c)}',style:TextStyle(color:s.onPrimary.withValues(alpha:.7),fontSize:10))]));}
 Widget _metric(ColorScheme s,String l,String v)=>Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(l,style:TextStyle(color:s.onPrimary.withValues(alpha:.65),fontSize:9)),const SizedBox(height:2),Text(v,style:TextStyle(color:s.onPrimary,fontSize:14,fontWeight:FontWeight.w700))]));
 Widget _section(BuildContext c,String t)=>Padding(padding:const EdgeInsets.fromLTRB(2,22,2,10),child:Text(t,style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)));
 Widget _guidance(BuildContext c,WeatherData w){final rows=[['Spraying',w.guidance.spraying],['Drying produce',w.guidance.drying],['Harvest and transport',w.guidance.transport],['Irrigation',w.guidance.irrigation]];return Card(child:Column(children:rows.map((r)=>ListTile(title:Text(r[0]),trailing:_status(c,r[1]))).toList()));}
 Widget _status(BuildContext c,String value){final s=Theme.of(c).colorScheme;final good={'Suitable','Not required','Check soil','Until afternoon'}.contains(value);final avoid={'Avoid','Not suitable'}.contains(value);return Text(value,style:TextStyle(color:avoid?s.error:good?s.primary:s.tertiary,fontWeight:FontWeight.w700));}
 Widget _hourly(BuildContext c,WeatherData w)=>SizedBox(height:135,child:ListView.separated(scrollDirection:Axis.horizontal,itemCount:w.hourly.length,itemBuilder:(c,i){final h=w.hourly[i];final dt=DateTime.tryParse(h.time);return Container(width:84,padding:const EdgeInsets.all(10),decoration:BoxDecoration(border:Border.all(color:Theme.of(c).colorScheme.outlineVariant),borderRadius:BorderRadius.circular(20)),child:Column(children:[Text(dt==null?'--':TimeOfDay.fromDateTime(dt).format(c),style:const TextStyle(fontSize:11)),const SizedBox(height:9),Icon(_glyph(h.weatherCode),size:22),const SizedBox(height:7),Text('${h.temperature?.round()??'--'}°',style:const TextStyle(fontSize:16,fontWeight:FontWeight.w700)),Text('${h.precipitationProbability?.round()??0}%',style:TextStyle(fontSize:12,color:Theme.of(c).colorScheme.primary))]));},separatorBuilder:(_,__)=>const SizedBox(width:8)));
 Widget _daily(BuildContext c,WeatherData w)=>Card(child:Column(children:w.forecast.map((d){final date=DateTime.tryParse(d.date);final day=date==null?d.date:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][date.weekday-1];return ListTile(title:Text(day,style:const TextStyle(fontWeight:FontWeight.w700)),leading:Text('${d.precipitationProbability?.round()??0}%',style:TextStyle(color:Theme.of(c).colorScheme.primary)),subtitle:Text('${d.temperatureMin?.round()??'--'}° / ${d.temperatureMax?.round()??'--'}°'),trailing:Text('${(d.precipitationMm??0).toStringAsFixed(1)} mm',style:Theme.of(c).textTheme.bodySmall));}).toList()));
 Widget _rainChips(BuildContext c,WeatherData w)=>Padding(padding:const EdgeInsets.only(top:12),child:Wrap(spacing:7,runSpacing:7,children:w.forecast.map((d){final date=DateTime.tryParse(d.date);final day=date==null?'--':['M','T','W','T','F','S','S'][date.weekday-1];return Chip(label:Text('${day ${d.precipitationProbability?.round()??0}%'));}).toList()));
 static IconData _glyph(int? code){if(code==null)return Icons.cloud_outlined;if(code==0)return Icons.wb_sunny_outlined;if(code<4)return Icons.cloud_outlined;if(code<50)return Icons.foggy;if(code<70)return Icons.grain;if(code<90)return Icons.water_drop_outlined;return Icons.thunderstorm_outlined;}
}
